  function addCompanyYear(year,values={}){const row=document.createElement('div');row.className='company-year';row.innerHTML='<label>Year<input class="year" type="number" min="1900" max="2200" step="1" required></label><label>Revenue<input class="revenue" type="number" step="any" placeholder="Amount"></label><label>Profit<input class="profit" type="number" step="any" placeholder="Amount"></label><button class="text-button" type="button" aria-label="Remove year">Remove</button>';row.querySelector('.year').value=year;row.querySelector('.revenue').value=values.revenue??'';row.querySelector('.profit').value=values.profit??'';row.querySelector('button').onclick=()=>row.remove();$('company-years').append(row);}
