  function suggestions(people){const themes=new Map(),signals=new Map(),circles=new Map();for(const p of people){if(p.theme)themes.set(p.theme,(themes.get(p.theme)||0)+1);const s=roleSignal(p.position);if(s!=='__other')signals.set(s,(signals.get(s)||0)+1);if(p.circle)circles.set(p.circle,(circles.get(p.circle)||0)+1);}const top=map=>[...map].sort((a,b)=>b[1]-a[1])[0]?.[0];const theme=top(themes),role=top(signals),circle=top(circles);const topic=theme==='AI & technology'?'where AI is useful in practice':theme==='Peer advisory'?'a challenge best explored with peers':theme==='Transformation'?'leading through change':theme==='Leadership'?'leadership choices under pressure':theme==='Growth'?'growth priorities and trade-offs':'a current business challenge';const audience=role==='Founder / owner'?'founders':role==='Executive leader'?'business leaders':role==='Marketing'?'marketing leaders':role==='Technology'?'technology leaders':role==='People / talent'?'people leaders':'people in this group';const ideas=[`Ask a thoughtful question about ${topic}; listen before offering anything.`,`Share one concise insight or resource on ${topic}, with a note on why it fits their situation.`,`Offer a relevant introduction between two ${audience} who could learn from each other.`,circle==='Peer leader'||theme==='Peer advisory'?`Invite a small peer conversation on ${topic} with a clear, useful question.`:`Invite a short exchange to compare experience on ${topic}, with no pitch.`,`Reconnect around a specific milestone at their company and ask what has changed since you last spoke.`];return {ideas,audience,topic};}
